Contract AutomatedTellerMachineSystem::depositFunds(quantity:Real): Boolean {
          definition:
          inputCard:BankCard = BankCard.allInstance()->any(o | o.Password = InputCard.Password and o.CardID = InputCard.CardID),

            precondition:
          PasswordValidated = true and CardIDValidated = true and InputCard.oclIsUndefined() = false and quantity >= 100 and inputCard.Balance.isEmpty() = false

            postcondition:
          let newCard:BankCard in newCard = inputCard.Balance + quantity, result = (newCard = true)

        }
